public class Ejemplo1 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub

		//1. Programa que muestra una matriz de * de n x m
		/*
		 *     n = 5 y m = 5
		 *     
		 *            * * * * *
		 *            * * * * *
		 *            * * * * *
		 *            * * * * *
		 *            * * * * *
		 * 
		 */
		
		
	for(int j = 0;j<10;j++) {	
		for(int i = 1;i<6;i++) {
			System.out.print("* ");
		}
		System.out.println();
	}
		
	}

}
